(1, 1, '1405-06-03', 4, 2, 3, 3, 4, 'اون چیزی که دلم میخاد اینجا نوشتم به یادگار', '2026-08-25 22:47:41'),
(2, 2, '1405-06-04', 5, 4, 3, 5, 3, 'خوب و بدی نیست این نگاه ماست که خوب و بد را درست میکنه', '2026-08-26 01:19:11'),
(3, 3, '1405-06-04', 5, 5, 5, 5, 2, 'امروز تولد جوماست', '2026-08-26 18:46:27'),
(4, 4, '1405-06-07', 5, 3, 4, 4, 3, 'امروز ', '2026-08-29 20:43:55'),
